function admin_t(string $key, string $lang = 'en'): string
{
    if ($key === 'footer') return [
        'tr'=>'Bağımsız yönetim platformu','en'=>'Independent management platform','de'=>'Unabhängige Verwaltungsplattform','fr'=>'Plateforme de gestion indépendante','es'=>'Plataforma de gestión independiente','it'=>'Piattaforma di gestione indipendente','pt'=>'Plataforma de gestão independente','nl'=>'Onafhankelijk beheerplatform','ru'=>'Независимая платформа управления','ar'=>'منصة إدارة مستقلة','fa'=>'پلتفرم مدیریت مستقل','zh'=>'独立管理平台','ja'=>'独立した管理プラットフォーム','ko'=>'독립 관리 플랫폼'
    ][$lang] ?? 'Independent management platform';
    $dictionary = admin_dictionary();
    return $dictionary[$lang][$key] ?? $dictionary['en'][$key] ?? $key;
}

