        'ja'=>['subject'=>'依頼状況の更新','reference'=>'依頼番号','status'=>'状況','datetime'=>'日付 / 時刻','offer'=>'見積もり','labels'=>['new'=>'新しい依頼','quoted'=>'見積もり送信済み','proposed'=>'日程提案済み','confirmed'=>'確定','rejected'=>'拒否']],
