    ][$lang];
    $body = $copy['reference'].': '.$reference."\n".$copy['status'].': '.($copy['labels'][$status] ?? $status)."\n".$copy['datetime'].': '.trim($date.' '.$slot);
    if ($price !== '') $body .= "\n".$copy['offer'].': '.$price.' '.$currency;
    return [$brand.' · '.$copy['subject'].' · '.$reference, $body];
}

